    "explanation": "\ud83d\udcd8 **NCERT Concept**:\n**Nuclear Dimorphism in Ciliates**: Ciliated protozoans like *Paramoecium* possess two distinct nuclei: a large polyploid macronucleus (vegetative/trophic functions) and a small diploid micronucleus (reproductive/conjugation functions).\n\n\u26a1 **Detailed Anatomical & Taxonomic Explanation**:\nEntamoeba, Leishmania, and Trypanosoma possess a single vesicular nucleus. Paramoecium distinctly displays nuclear dimorphism.\n- Selected Correct Option: **(4) Paramoecium**\n- Phylum / Domain Focus: *Protozoans (Kingdom Protista)*\n\n\ud83d\udca1 **Examiner Pro-Tip**:\nRemember: Macronucleus controls metabolic activity; micronucleus controls genetic recombination during conjugation."
